const settings = $("Set post and narration options").first().json;
const current = articleBody($input.first().json, settings.postId);
if ($("Check for existing narration").first().json.article.raw !== current.raw)
  throw new Error("WordPress article changed before media upload. Start over from the trigger.");
return [{ json: {} }];

function wordpressId(value, label) {
  if (!Number.isSafeInteger(value) || value < 1)
    throw new Error(label + " must be a positive WordPress ID");
  return value;
}

function httpsResource(value) {
  if (
    typeof value !== "string" ||
    !/^https:\/\/[A-Za-z0-9.-]+(?::\d{1,5})?(?:[/?][^\s"'<>]*)?$/i.test(value)
  ) {
    throw new Error("WordPress media needs a valid HTTPS source URL");
  }
  return value;
}

function confirmMedia(media, settings) {
  const id = wordpressId(media?.id, "Uploaded media ID");
  const sourceUrl = httpsResource(media.source_url);
  const name = sourceUrl.split("?")[0].split("/").at(-1);
  const suffix = name.slice(settings.attachment.length);
  if (
    media.post !== settings.postId ||
    !["audio/mpeg", "audio/mp3"].includes(media.mime_type) ||
    !name.startsWith(settings.attachment) ||
    !/^(?:-\d+)?\.mp3$/.test(suffix) ||
    (settings.reuseMediaId && id !== settings.reuseMediaId)
  ) {
    throw new Error("WordPress media does not match the MP3 for this post and narration mode");
  }
  return { mediaId: id, sourceUrl };
}

const media = confirmMedia($input.first().json, $("Set post and narration options").first().json);
return [{ json: media }];

const saved = $input.first().json;
const media = $("Verify the attachment belongs to this post").first().json;
if (
  saved.post_key !== $("Set post and narration options").first().json.key ||
  saved.status !== "pending_post_update" ||
  Number(saved.media_id) !== media.mediaId
) {
  throw new Error("The WordPress media checkpoint was not confirmed");
}
return [{ json: { mediaId: media.mediaId } }];

function articleBody(post, postId) {
  if (
    post?.id !== postId ||
    typeof post.content?.raw !== "string" ||
    !post.content.raw.trim() ||
    typeof post.content.rendered !== "string" ||
    !post.content.rendered.trim()
  ) {
    throw new Error(
      "WordPress did not return editable and rendered content for the requested post ID",
    );
  }
  return { raw: post.content.raw, rendered: post.content.rendered };
}

function assembleArticle(article, current, media, mode) {
  if (article.raw !== current.raw)
    throw new Error(
      "The WordPress article changed. Review the uploaded media before updating the post.",
    );
  const url = media.sourceUrl.replaceAll("&", "&amp;");
  const title =
    mode === "summary" ? "Listen to the article summary." : "Listen to the full article.";
  const attrs = JSON.stringify({ id: media.mediaId, className: "wp-article-narration" });
  return (
    "<!-- wp:audio " +
    attrs +
    " -->\n" +
    '<figure class="wp-block-audio wp-article-narration"><audio controls="controls" src="' +
    url +
    '"></audio><figcaption class="wp-element-caption">' +
    title +
    "</figcaption></figure>\n" +
    "<!-- /wp:audio -->\n\n" +
    article.raw
  );
}

const settings = $("Set post and narration options").first().json;
const media = $("Verify the attachment belongs to this post").first().json;
const content = assembleArticle(
  $("Check for existing narration").first().json.article,
  articleBody($input.first().json, settings.postId),
  media,
  settings.mode,
);
return [{ json: { content } }];

